// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzing over caller address and sent amount. The general rule:
    // Reference C accepts only calls with exactly 10 ether; any other amount reverts.
    // We assert that for all inputs where amount != 10 ether, the call to fallback reverts (ok==false).
    // The mutant that changed the requirement to 1 ether will accept calls with 1 ether and thus
    // break this universal property for some fuzzed amounts (e.g., 1 ether).
    function testFuzz_property(address caller, uint256 amount) public {
        // keep caller useful (non-zero) to avoid degenerate zero-address pruning
        vm.assume(caller != address(0));

        // bound amount to a reasonably wide range but within payable limits
        amount = bound(amount, 0, 20 ether);

        // prepare caller with funds
        vm.deal(caller, 20 ether);

        bool ok;
        // perform the call as the caller, sending the fuzzed amount
        vm.prank(caller);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ALL callers and ALL amounts not equal to 10 ether,
        // the reference contract must reject (revert) the call, so ok == false.
        // We therefore assert that if amount != 10 ether then the call did NOT succeed.
        if (amount != 10 ether) {
            assertTrue(!ok);
        } else {
            // If the amount is exactly 10 ether, the reference accepts the call (ok == true).
            assertTrue(ok);
        }
    }
}

