import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the sent amount and the caller address (caller must be funded)
    function testFuzz_property(uint256 amount, address sender) public {
        // admissible domain: amount should be a reasonable ether value within uint128 to avoid vm.deal limits
        // but keep it wide: allow any uint256 mapped into 0..100 ether range
        uint256 amt = bound(amount, 0, 100 ether);
        address actor = sender;
        if (actor == address(0)) { actor = address(1); }

        // fund the actor so it can send amt
        vm.deal(actor, amt + 1 ether);

        // perform the low-level call to fallback by sending ETH with empty calldata
        bool ok;
        vm.prank(actor);
        (bool success, ) = address(c).call{value: amt}("");
        ok = success;

        // General rule: reference C only accepts calls with exactly 10 ether.
        // Therefore for ALL inputs, c.accepts == (amt == 10 ether).
        // We assert that the observed acceptance equals (amt == 10 ether).
        // This holds for the reference contract for every input; the mutant that requires 1 ether
        // will accept when amt == 1 ether, so for some fuzz inputs this assertion will fail.
        assertTrue(ok == (amt == 10 ether));
    }
}

