pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: two callers and a block number to place the call on a block where block.number % 15 == 0
    function testFuzz_property(address caller1, address caller2, uint256 targetBlock) public {
        // keep addresses non-zero and distinct
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(caller1 != caller2);

        // constrain targetBlock to a reasonable range to avoid extremely large warps
        targetBlock = bound(targetBlock, block.number, block.number + 1000);

        // find a block >= current where block.number % 15 == 0 so the conditional transfer branch is reachable
        uint256 b = targetBlock;
        // advance forward until we hit a block divisible by 15 (keep search bounded)
        for (uint256 i = 0; i < 20; i++) {
            if (b % 15 == 0) break;
            b++;
        }
        vm.assume(b % 15 == 0);

        // Warp to the target block and a fixed timestamp for the block
        // Use a chosen timestamp value; keep it wide by deriving from block.timestamp
        uint256 ts = block.timestamp + 1;
        vm.warp(ts);
        // Move to the chosen block number (vm.roll available in forge)
        vm.roll(b);

        // Fund callers
        vm.deal(caller1, 20 ether);
        vm.deal(caller2, 20 ether);

        // First call: caller1 sends exactly 10 ether; should succeed on both reference and mutant
        vm.prank(caller1);
        payable(address(c)).call{value: 10 ether}("");

        // Record state after first call
        uint256 pastAfterFirst = c.pastBlockTime();
        // Ensure it updated to current block timestamp
        // (This read only used to observe contract behavior; assertion later will be single assert)

        // Second call: same block timestamp (we do not change timestamp or roll block)
        vm.prank(caller2);
        (bool okSecond, ) = payable(address(c)).call{value: 10 ether}("");

        // After the second call completes, check if pastBlockTime changed.
        // For the correct contract, the second call in the same block MUST be rejected by require(block.timestamp > pastBlockTime)
        // so either okSecond == false (revert) or pastBlockTime remains unchanged. However, because require will revert,
        // the second call will not change state; therefore reading pastBlockTime should equal pastAfterFirst.

        // Single assertion required: the reference contract guarantees pastBlockTime did not change after the second call
        // (i.e., pastBlockTime == pastAfterFirst). The mutant with >= allows the second call to pass and would update
        // pastBlockTime to the same timestamp — which still equals pastAfterFirst, so to expose mutant we rely on transfer behavior.
        // To ensure the transfer difference manifests, we chose a block number divisible by 15; on the reference the second call reverts
        // and therefore cannot trigger the transfer, leaving contract balance at 10 ether. On the mutant the second call can succeed
        // and will transfer full balance to caller2, leaving contract balance 0. Thus assertTrue reading address(c).balance == 10 ether
        // will hold for the reference for all inputs but fail for the mutant for some inputs the fuzzer finds.

        assertTrue(address(c).balance == 10 ether);
    }
}

