pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an address to act as caller and a uint256 representing a block timestamp to warp to
    function testFuzz_property(address caller, uint256 warpTime) public {
        // Keep caller non-zero
        vm.assume(caller != address(0));

        // Keep warpTime in a reasonable range (non-negative and within uint32-ish bounds) to avoid weirdness
        warpTime = bound(warpTime, 1, type(uint32).max);

        // Fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // First call: warp to warpTime, perform a payable fallback with exactly 10 ether
        vm.warp(warpTime);
        vm.prank(caller);
        // send exactly 10 ether to trigger fallback
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        // After first call, if it succeeded, pastBlockTime should have been set to block.timestamp (warpTime)
        // Capture the stored pastBlockTime via auto getter
        uint256 after1 = c.pastBlockTime();

        // Second call: same block timestamp (do not change warp), attempt another fallback with 10 ether
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The universal property for the reference: it's impossible for two successful fallback calls in the same block
        // to both succeed and thus for the second call to also return true. Therefore, at most one of ok1/ok2 is true.
        // This assertion reads c via its getter and the boolean result of the second call (ok2) is observed via the try/call capture.
        // We enforce the admissible domain widely (any caller, any reasonable warp time) and assert the invariant.
        // Exactly one assertTrue as required.
        assertTrue(!(ok1 && ok2));
    }
}

