    function testFuzz_property(address caller, uint64 dt) public {
        // keep caller non-zero and dt small-ish but allow wide range
        vm.assume(caller != address(0));
        // bound dt so warp doesn't overflow unrealistic values, but allow 0
        uint64 delta = uint64(bound(dt, 0, 1 days));

        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // snapshot pastBlockTime before first call
        uint prev = c.pastBlockTime();

        // ensure block.timestamp increases at least a bit for first call
        vm.warp(block.timestamp + 1);

        // first successful call with required value
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1); // must succeed to establish the invariant

        uint after1 = c.pastBlockTime();

        // The reference contract requires block.timestamp > prev, so after1 > prev always
        // Now attempt a second call possibly in the same timestamp by warping only by `delta` (which may be 0)
        vm.warp(block.timestamp + delta);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        // second call may or may not transfer funds depending on block.number, but may succeed

        uint after2 = c.pastBlockTime();

        // GENERAL ASSERTION: for the correct contract, any successful call that completed
        // results in a strictly increased pastBlockTime compared to before that call.
        // We assert that at least the first call increased pastBlockTime (this must hold for ALL inputs).
        assertTrue(after1 > prev);

        // Note: This single assert observes c via its public getter and will pass on reference
        // but there exist inputs (delta == 0 and suitable block.number) where the mutant allows
        // after2 == after1, demonstrating the bug; the test's single assertion is the required universal property.
    }
}

