pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: actor (caller) and two block timestamps to control same-timestamp scenario
    function testFuzz_property(address actor, uint64 ts) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // Bound the timestamp to a reasonable range to avoid overflow in vm.warp
        ts = uint64(bound(ts, 1, type(uint64).max - 1));

        // Give actor enough ether to make two 10 ether calls
        vm.deal(actor, 20 ether);

        // First call: warp to ts and call fallback with 10 ether
        vm.warp(uint256(ts));
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Record pastBlockTime after first successful call
        uint first = c.pastBlockTime();

        // Second call: keep same timestamp to simulate the edge the mutant accepts
        vm.warp(uint256(ts)); // same timestamp
        vm.prank(actor);

        // Attempt second call and record whether it succeeded
        bool secondSucceeded;
        try c.f{value: 10 ether}() {
            secondSucceeded = true;
        } catch {
            secondSucceeded = false;
        }

        // In the reference contract, either the second call reverts (so secondSucceeded==false),
        // or, if it succeeded, pastBlockTime strictly increased compared to first.
        // Therefore the property we assert is: secondSucceeded implies c.pastBlockTime() > first.
        // This holds for the correct contract; the mutant (which removed the require) can have
        // secondSucceeded==true and c.pastBlockTime() == first, violating the property.
        if (secondSucceeded) {
            assertTrue(c.pastBlockTime() > first);
        } else {
            // If second call reverted, the property is trivially satisfied; assert a tautology reading c
            assertTrue(address(c).balance >= 0);
        }
    }
}

