pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: actor (the caller) and an initial timestamp warp value
    function testFuzz_property(address actor, uint64 warpTime) public {
        // admissible domain: actor must be non-zero and warpTime reasonable
        vm.assume(actor != address(0));
        // ensure warpTime is within uint256 range and not ridiculously large
        uint256 wt = uint256(warpTime);
        vm.warp(wt);

        // give actor enough balance
        vm.deal(actor, 20 ether);

        // first call: must send exactly 10 ether and should succeed on reference
        vm.prank(actor);
        // perform low-level call to trigger fallback
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        // require the first call succeeded for the scenario (if it reverts here, property still holds vacuously)
        // but we continue only if ok1 is true
        if (!ok1) {
            // If first call reverts, reference's require likely rejected; property (that successful calls enforce timestamp ordering)
            // still holds universally; assertTrue over that observation: the contract did not accept the first call.
            // We read address(c).balance to observe behavior: if first call failed, balance remains 0.
            assertTrue(address(c).balance == 0);
            return;
        }

        // read pastBlockTime after first successful call
        uint256 t_after_first = c.pastBlockTime();

        // Now attempt a second call at the SAME block.timestamp (no warp change)
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The universal rule we assert: whenever a call with exactly 10 ether succeeds, it must enforce timestamp ordering
        // Concretely: under the reference, a second call at the same block.timestamp cannot both succeed and leave pastBlockTime equal to its previous value.
        // We assert that either the second call reverted (ok2 == false) OR, if it succeeded, pastBlockTime strictly increased.
        if (!ok2) {
            // second call reverted; reference satisfies the rule for this input
            assertTrue(true);
            return;
        }

        // second call succeeded; then pastBlockTime must have increased
        uint256 t_after_second = c.pastBlockTime();
        assertTrue(t_after_second > t_after_first);
    }
}

