import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing over block number and caller address (and caller initial balance)
    // We need at least one fuzz parameter; choose uint256 roll (block number) and address actor
    function testFuzz_property(uint256 roll, address actor) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // bound roll to a reasonable blockchain block number range
        uint256 blockNum = bound(roll, 1, type(uint256).max - 1);

        // We need to send exactly 10 ether per the contract requirement
        uint256 sendAmount = 10 ether;

        // Fund actor so they can send
        vm.deal(actor, sendAmount + 1 ether);

        // Advance to a later timestamp than pastBlockTime (initially 0) and set block number
        // vm.roll sets block.number; vm.warp sets timestamp
        vm.roll(blockNum);
        vm.warp(block.timestamp + 1);

        // make the call from actor sending exactly 10 ether
        vm.prank(actor);
        c.f{value: sendAmount}();

        // The universal property (we assert it): After the call, for the reference contract, if the current block number is NOT divisible by 15,
