        // prepare caller with funds
        vm.deal(caller, 20 ether);

        // set a past time so that block.timestamp > pastBlockTime will hold after warp
        // ensure we advance time at least 1 second
        vm.warp(block.timestamp + timeAdvance);

        // set block number such that sometimes it's divisible by 15; let fuzzer choose
        vm.roll(blockNumber);

        // perform the payable fallback call as the caller with exactly 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The universal property for the reference: if current block.number % 15 == 0 then the contract's balance is 0
        // We assert that: when block.number % 15 == 0 => address(c).balance == 0
        // This will hold for the reference implementation for all inputs, but the mutant that transfers only 1 ether
        // will leave balance > 0 for some inputs (when address(c).balance prior to transfer > 1 ether).
        if (blockNumber % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            // when not divisible by 15, no universal claim about balance; assert true to keep single assert in branch
            assertTrue(true);
        }
    }
}

