pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: blockNumber and caller address (caller must be funded)
    function testFuzz_property(uint256 fuzzBlockNumber, address caller) public {
        // keep block number in a reasonable range and nonzero
        uint256 bn = bound(fuzzBlockNumber, 1, type(uint64).max);
        vm.roll(bn);

        // ensure timestamp advances so block.timestamp > pastBlockTime (pastBlockTime initially 0)
        // Use vm.warp to set a timestamp greater than 0
        vm.warp(block.timestamp + 1);

        // choose a caller that is not the zero address and fund it
        vm.assume(caller != address(0));
        vm.deal(caller, 20 ether);

        // Caller sends exactly 10 ether to trigger fallback
        vm.prank(caller);
        // send 10 ether; call will succeed only if msg.value == 10 ether and timestamp > pastBlockTime
        (bool ok,) = address(c).call{value: 10 ether}("");
        // We only assert a universal property about the contract state after admissible successful calls
        // So require that the call succeeded and that this block triggers the conditional (bn % 15 == 0)
        // If call failed or condition not met, the property is vacuously true for that input; we only
        // assert when the admissible conditions hold.

        if (ok && (bn % 15 == 0)) {
            // After a successful fallback on a block divisible by 15, the reference implementation
            // transfers the entire contract balance to the caller, leaving address(c).balance == 0.
            // This is the single assertion reading c's external observable state.
            assertTrue(address(c).balance == 0);
        }
    }
}
